import React, { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { Plus, Search, Filter, Rocket, Play, Square, RefreshCw, AlertCircle } from 'lucide-react';
import DeploymentCard from '../components/deployments/DeploymentCard';
import Modal from '../components/common/Modal';
import toast from 'react-hot-toast';

const Deployments = () => {
  const [deployments, setDeployments] = useState([
    {
      id: 1,
      name: 'Frontend App v2.3.1',
      project: 'E-Commerce Platform',
      environment: 'Production',
      status: 'success',
      timestamp: new Date(Date.now() - 1000 * 60 * 5),
      duration: '3m 24s',
      url: 'https://app.ecommerce.com',
      version: 'v2.3.1',
      branch: 'main',
      deployedBy: 'Admin',
      commit: 'a7f3b9c',
    },
    {
      id: 2,
      name: 'API Gateway v1.2.0',
      project: 'Microservices',
      environment: 'Staging',
      status: 'running',
      timestamp: new Date(Date.now() - 1000 * 60 * 30),
      duration: '2m 15s',
      url: 'https://staging-api.gateway.com',
      version: 'v1.2.0',
      branch: 'develop',
      deployedBy: 'Dev Team',
      commit: 'e8d4a2f',
    },
    {
      id: 3,
      name: 'Database Migration',
      project: 'Analytics Pipeline',
      environment: 'Production',
      status: 'failed',
      timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2),
      duration: '1m 45s',
      url: '',
      version: 'v3.0.0',
      branch: 'main',
      deployedBy: 'Admin',
      commit: 'c9b6a3e',
    },
    {
      id: 4,
      name: 'Auth Service v4.1.2',
      project: 'User Management',
      environment: 'Production',
      status: 'pending',
      timestamp: new Date(Date.now() - 1000 * 60 * 60 * 5),
      duration: '',
      url: 'https://auth.users.com',
      version: 'v4.1.2',
      branch: 'main',
      deployedBy: 'Admin',
      commit: 'd1e5f8a',
    },
    {
      id: 5,
      name: 'Notification Service v2.0',
      project: 'Communication Platform',
      environment: 'Production',
      status: 'stopped',
      timestamp: new Date(Date.now() - 1000 * 60 * 60 * 24),
      duration: '4h 12m',
      url: 'https://notify.com',
      version: 'v2.0.0',
      branch: 'main',
      deployedBy: 'Admin',
      commit: 'f2a3b4c',
    },
  ]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterEnvironment, setFilterEnvironment] = useState('all');
  const [selectedDeployment, setSelectedDeployment] = useState(null);

  const [formData, setFormData] = useState({
    name: '',
    project: '',
    environment: 'Production',
    version: 'v1.0.0',
    branch: 'main',
  });

  const handleOpenModal = () => {
    setFormData({
      name: '',
      project: '',
      environment: 'Production',
      version: 'v1.0.0',
      branch: 'main',
    });
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  const handleDeploy = (e) => {
    e.preventDefault();
    
    if (!formData.name.trim() || !formData.project.trim()) {
      toast.error('Name and project are required');
      return;
    }

    const newDeployment = {
      id: Date.now(),
      ...formData,
      status: 'pending',
      timestamp: new Date(),
      duration: '',
      url: '',
      deployedBy: 'Admin',
      commit: Math.random().toString(36).substring(2, 9),
    };

    setDeployments([newDeployment, ...deployments]);
    toast.success('Deployment started successfully!');
    
    // Simulate deployment progress
    setTimeout(() => {
      setDeployments(prev => prev.map(d => 
        d.id === newDeployment.id 
          ? { ...d, status: 'running' }
          : d
      ));
    }, 2000);

    setTimeout(() => {
      setDeployments(prev => prev.map(d => 
        d.id === newDeployment.id 
          ? { ...d, status: 'success', duration: '2m 30s' }
          : d
      ));
      toast.success(`${formData.name} deployed successfully! 🎉`);
    }, 5000);

    handleCloseModal();
  };

  const handleRedeploy = (id) => {
    const deployment = deployments.find(d => d.id === id);
    if (deployment) {
      toast.loading(`Redeploying ${deployment.name}...`);
      setDeployments(prev => prev.map(d =>
        d.id === id
          ? { ...d, status: 'pending', timestamp: new Date() }
          : d
      ));
      setTimeout(() => {
        setDeployments(prev => prev.map(d =>
          d.id === id
            ? { ...d, status: 'success', duration: '2m 15s' }
            : d
        ));
        toast.success(`${deployment.name} redeployed successfully!`);
      }, 3000);
    }
  };

  const handleStop = (id) => {
    const deployment = deployments.find(d => d.id === id);
    if (deployment && window.confirm(`Stop ${deployment.name}?`)) {
      setDeployments(prev => prev.map(d =>
        d.id === id
          ? { ...d, status: 'stopped' }
          : d
      ));
      toast.success(`${deployment.name} stopped successfully`);
    }
  };

  const handleViewLogs = (id) => {
    const deployment = deployments.find(d => d.id === id);
    if (deployment) {
      toast.success(`Opening logs for ${deployment.name}...`);
      // In a real app, this would open a logs modal or page
      setSelectedDeployment(deployment);
    }
  };

  const getStatusCount = (status) => {
    return deployments.filter(d => d.status === status).length;
  };

  const filteredDeployments = deployments.filter(deployment => {
    const matchesSearch = deployment.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          deployment.project.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = filterStatus === 'all' || deployment.status === filterStatus;
    const matchesEnvironment = filterEnvironment === 'all' || deployment.environment === filterEnvironment;
    return matchesSearch && matchesStatus && matchesEnvironment;
  });

  const stats = {
    total: deployments.length,
    success: getStatusCount('success'),
    running: getStatusCount('running'),
    failed: getStatusCount('failed'),
    pending: getStatusCount('pending'),
  };

  return (
    <>
      <Helmet><title>Deployments</title></Helmet>
      
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white">🚀 Deployments</h1>
            <p className="text-gray-600 dark:text-gray-300 mt-1">Deploy and manage your applications</p>
          </div>
          <button
            onClick={handleOpenModal}
            className="mt-4 md:mt-0 inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-5 h-5 mr-2" />
            New Deployment
          </button>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-6">
          <div className="bg-white dark:bg-gray-800 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
            <p className="text-sm text-gray-500 dark:text-gray-400">Total</p>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">{stats.total}</p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
            <p className="text-sm text-gray-500 dark:text-gray-400">Success</p>
            <p className="text-2xl font-bold text-green-600">{stats.success}</p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
            <p className="text-sm text-gray-500 dark:text-gray-400">Running</p>
            <p className="text-2xl font-bold text-blue-600">{stats.running}</p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
            <p className="text-sm text-gray-500 dark:text-gray-400">Failed</p>
            <p className="text-2xl font-bold text-red-600">{stats.failed}</p>
          </div>
          <div className="bg-white dark:bg-gray-800 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
            <p className="text-sm text-gray-500 dark:text-gray-400">Pending</p>
            <p className="text-2xl font-bold text-yellow-600">{stats.pending}</p>
          </div>
        </div>

        {/* Search & Filter */}
        <div className="flex flex-col sm:flex-row gap-4 mb-6">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search deployments..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
          >
            <option value="all">All Status</option>
            <option value="success">Success</option>
            <option value="running">Running</option>
            <option value="failed">Failed</option>
            <option value="pending">Pending</option>
            <option value="stopped">Stopped</option>
          </select>
          <select
            value={filterEnvironment}
            onChange={(e) => setFilterEnvironment(e.target.value)}
            className="px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
          >
            <option value="all">All Environments</option>
            <option value="Production">Production</option>
            <option value="Staging">Staging</option>
            <option value="Development">Development</option>
          </select>
        </div>

        {/* Deployments List */}
        {filteredDeployments.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-6xl mb-4">📦</div>
            <h3 className="text-xl font-semibold text-gray-900 dark:text-white">No deployments found</h3>
            <p className="text-gray-500 dark:text-gray-400 mt-2">Deploy your first application</p>
            <button
              onClick={handleOpenModal}
              className="mt-4 inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
            >
              <Rocket className="w-5 h-5 mr-2" />
              New Deployment
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredDeployments.map((deployment) => (
              <DeploymentCard
                key={deployment.id}
                deployment={deployment}
                onRedeploy={handleRedeploy}
                onStop={handleStop}
                onViewLogs={handleViewLogs}
              />
            ))}
          </div>
        )}

        {/* New Deployment Modal */}
        <Modal
          isOpen={isModalOpen}
          onClose={handleCloseModal}
          title="New Deployment"
          size="md"
        >
          <form onSubmit={handleDeploy} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Deployment Name *
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                placeholder="e.g., Frontend App v2.3.1"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Project *
              </label>
              <input
                type="text"
                value={formData.project}
                onChange={(e) => setFormData({ ...formData, project: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                placeholder="Project name"
                required
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Environment
                </label>
                <select
                  value={formData.environment}
                  onChange={(e) => setFormData({ ...formData, environment: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                >
                  <option value="Production">Production</option>
                  <option value="Staging">Staging</option>
                  <option value="Development">Development</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Version
                </label>
                <input
                  type="text"
                  value={formData.version}
                  onChange={(e) => setFormData({ ...formData, version: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                  placeholder="v1.0.0"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Branch
              </label>
              <input
                type="text"
                value={formData.branch}
                onChange={(e) => setFormData({ ...formData, branch: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                placeholder="main"
              />
            </div>

            <div className="flex justify-end space-x-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <button
                type="button"
                onClick={handleCloseModal}
                className="px-4 py-2 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center"
              >
                <Rocket className="w-4 h-4 mr-2" />
                Deploy
              </button>
            </div>
          </form>
        </Modal>
      </div>
    </>
  );
};

export default Deployments;
